/**
 * Builds the modules Canon ships (docs/modules.md, "Modules Canon ships"). Each `modules/examples/<slug>/` holds a
 * module.json and its server.ts; this writes each one's server bundle (dist/module.js) and
 * modules/examples/_examples.generated.ts, the files Convex installs from with no GitHub (`canon:<slug>`), each with
 * the hash an install pins. Any problem in a module fails the build.
 *
 *   node --experimental-strip-types scripts/build-module-examples.ts
 *
 * tests/modules.test.ts fails when a bundle or the generated file is stale.
 */
import { mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { MODULE_FILE, parseModuleManifest } from "../modules/kernel/manifest.ts";
import { bundleHash } from "../modules/kernel/bundleHash.ts";
import { buildModule } from "../modules/kernel/tools/build.ts";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
export const EXAMPLES_DIR = join(ROOT, "modules", "examples");
export const EXAMPLES_FILE = join(EXAMPLES_DIR, "_examples.generated.ts");

/** Each example's directory, by slug (the name of its id, which is its address). */
function exampleDirs(): Array<{ slug: string; dir: string }> {
  return readdirSync(EXAMPLES_DIR).sort().flatMap((name) => {
    const dir = join(EXAMPLES_DIR, name);
    if (!statSync(dir).isDirectory()) return [];
    const parsed = parseModuleManifest(JSON.parse(readFileSync(join(dir, MODULE_FILE), "utf8")));
    if (!parsed.ok) throw new Error(`${relative(ROOT, join(dir, MODULE_FILE))}:\n  ${parsed.errors.join("\n  ")}`);
    const slug = parsed.manifest.id.slice(parsed.manifest.id.indexOf("/") + 1);
    if (slug !== name) throw new Error(`${relative(ROOT, dir)} holds ${parsed.manifest.id}: name the directory ${slug}`);
    return [{ slug, dir }];
  });
}

/** Every example built: its bundle (path and code) and the generated file's text. */
export async function buildExamples(): Promise<{ bundles: Array<{ path: string; code: string }>; generated: string }> {
  const bundles: Array<{ path: string; code: string }> = [];
  const entries: string[] = [];
  for (const { slug, dir } of exampleDirs()) {
    const manifest = readFileSync(join(dir, MODULE_FILE), "utf8");
    const built = JSON.parse(manifest).server ? await buildModule(dir) : null;
    if (built) bundles.push({ path: built.path, code: built.code });
    const bundle = built?.code ?? null;
    const sha = await bundleHash(`${manifest}\n${bundle ?? ""}`);
    entries.push(`  ${JSON.stringify(slug)}: { sha: ${JSON.stringify(sha)}, manifest: ${JSON.stringify(manifest)}, bundle: ${JSON.stringify(bundle)} },`);
  }
  const generated = [
    "// Generated by scripts/build-module-examples.ts from modules/examples/<slug>/. Do not edit: run it again.",
    "/** The modules Canon ships, by slug: module.json as written, its server bundle, and the hash an install pins. */",
    "export const MODULE_EXAMPLES: Record<string, { sha: string; manifest: string; bundle: string | null }> = {",
    ...entries,
    "};",
    "",
  ].join("\n");
  return { bundles, generated };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { bundles, generated } = await buildExamples();
  for (const b of bundles) {
    mkdirSync(dirname(b.path), { recursive: true });
    writeFileSync(b.path, b.code);
    console.log(`wrote ${relative(process.cwd(), b.path)} (${b.code.length} bytes)`);
  }
  writeFileSync(EXAMPLES_FILE, generated);
  console.log(`wrote ${relative(process.cwd(), EXAMPLES_FILE)}`);
}
